import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
        except StopIteration:
            break

        if N == 3:
            results.append("2 3 6")
            continue

        A = [0] * N
        for i in range(N):
            A[i] = (i + 1) * (N + 1)

        A[0] = (N + 1)

        results.append(" ".join(map(str, A)))

    print("\n".join(results))

if __name__ == "__main__":
    solve()
